import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  /**
   * Registers a tool with the registry.
   * If definition is a static object, its schema is compiled once at registration time.
   * [stated in specs/hal-engine-tool-input-validation/spec.md]
   */
  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      // Compile static tool's schema once at register time so a broken schema fails at startup
      compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = getValidator(definition.name, definition.inputSchema);

    if (!validate(input)) {
      const errors = validate.errors ?? [];
      const validationErrors = errors.map(err => {
        // Ajv 8 uses instancePath, Ajv 6 uses dataPath
        const rawPath = err.instancePath ?? (err as any).dataPath ?? '';
        const path = rawPath.replace(/^\//, '').replace(/^\./, '').replace(/\//g, '.');
        if (err.keyword === 'required') {
          const missing = err.params.missingProperty;
          return `${path ? `${path}.` : ''}${missing}: is required`;
        }
        return `${path}: ${err.message}`;
      });
      const result = `Validation failed: ${validationErrors.join('; ')}`;
      log.warn('tool', 'validation failed', {name, errors: validationErrors});
      return {result};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const schemaCache = new WeakMap<Record<string, unknown>, ValidateFunction>();

function getValidator(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  let validator = schemaCache.get(schema);
  if (!validator) {
    validator = compileSchema(toolName, schema);
    schemaCache.set(schema, validator);
  }
  return validator;
}

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {
      cause: error,
    });
  }
}

import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes through extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: any;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        receivedInput = input;
        return 'ok';
      }
    );

    const input = {a: 'hello', extra: 123};
    await registry.execute('test_tool', input);

    expect(receivedInput).toEqual({a: 'hello', extra: 123});
  });

  it('throws Unknown tool: <name> for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('validates against the current schema for function-valued definitions', async () => {
    const registry = new ToolRegistry();
    let schema: any = {type: 'object', properties: {a: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'dynamic',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    // First call: 'a' is string
    const resp1 = await registry.execute('dynamic_tool', {a: 123});
    expect(resp1.result).toContain('a:');
    expect(resp1.result.toLowerCase()).toContain('string');

    // Change schema object: 'a' is now number
    schema = {type: 'object', properties: {a: {type: 'number'}}};
    const resp2 = await registry.execute('dynamic_tool', {a: 'hello'});
    expect(resp2.result).toContain('a:');
    expect(resp2.result.toLowerCase()).toContain('number');
  });

  it('asserts a static tool\'s schema is compiled once across ten execute calls', async () => {
    const originalCompile = Ajv.prototype.compile;
    let callCount = 0;
    Ajv.prototype.compile = function(...args: any[]) {
      callCount++;
      return originalCompile.apply(this, args);
    };

    try {
      const registry = new ToolRegistry();

      registry.register(
        {
          name: 'static_tool',
          description: 'static',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      // Initial compile at registration
      expect(callCount).toBe(1);

      for (let i = 0; i < 10; i++) {
        await registry.execute('static_tool', {a: 'hello'});
      }

      // Should still be 1 (cached)
      expect(callCount).toBe(1);
    } finally {
      Ajv.prototype.compile = originalCompile;
    }
  });

  it('redacts property values from rejection messages and logs', async () => {
    const recordedLogs: any[] = [];
    const logger: Logger = {
      debug: () => {},
      info: () => {},
      warn: (_cat, _msg, fields) => recordedLogs.push(fields),
      error: () => {},
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secret_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {secret: {type: 'string'}},
          required: ['secret'],
        },
      },
      async () => 'ok'
    );

    const sensitiveValue = 'MY-SECRET-123';
    const resp = await registry.execute('secret_tool', {secret: 123}); // Wrong type

    expect(resp.result).toContain('secret');
    expect(resp.result).not.toContain(sensitiveValue);
    expect(recordedLogs.some(f => JSON.stringify(f).includes(sensitiveValue))).toBe(false);
  });
});

